miniLab.verifyScript:
# Goose Contributor Academy - Unit 2 exam miniLab: scratch-fork PR simulator
# Grading: fmt + clippy + tests + regression coverage + parity note +
# GOOSE_STATE_MACHINE=1 mention, all in lightweight form.
param(
    [string]$ForkDir = ""
)

$ErrorActionPreference = "Stop"
$fails = 0
$passes = 0

if (-not $ForkDir) {
    $ForkDir = Join-Path (Get-Location) "u2-exam-fork"
    Write-Host "[INFO]  ForkDir not set; trying default: $ForkDir"
}

function Check {
    param([string]$Name, [bool]$Ok, [string]$Detail)
    if ($Ok) {
        Write-Host "[PASS]  $Name"
        $script:passes++
    } else {
        Write-Host "[FAIL]  $Name - $Detail"
        $script:fails++
    }
}

$crate = Join-Path $ForkDir "fixer"
$lib = Join-Path $crate "src\lib.rs"
$tests = Join-Path $crate "tests\truncate_label_regression.rs"
$pr = Join-Path $crate "PR.md"

# 1. Scratch fork is a git repo
Check "fork is a git repo" (Test-Path (Join-Path $ForkDir ".git")) "run git init in u2-exam-fork"

# 2. Seeded bug replaced: no byte slicing remains, char-safe API present
$libOk = $false
if (Test-Path $lib) {
    $l = Get-Content $lib -Raw
    $libOk = ($l -match "fn truncate_label") -and ($l -match "chars\(\)") -and ($l -notmatch "text\[\.\.max\]")
}
Check "lib.rs has char-safe truncate_label (no byte slice)" $libOk "use chars().take(max).collect() pattern"

# 3. Two named regression tests exist
$testsOk = $false
if (Test-Path $tests) {
    $t = Get-Content $tests -Raw
    $testsOk = ($t -match "multibyte_label_never_panics") -and ($t -match "exact_fit_returns_original") -and ($t -match "#\[test\]")
}
Check "both regression tests present" $testsOk "multibyte_label_never_panics + exact_fit_returns_original"
if ($testsOk) { Write-Host "REGRESSION-TESTS: 2" } else { Write-Host "REGRESSION-TESTS: FAILED" }

# 4. PR.md verification plan markers
$prOk = $false
$prRaw = ""
if (Test-Path $pr) {
    $prRaw = Get-Content $pr -Raw
    $prOk = ($prRaw -match "Tests") -and ($prRaw -match "cargo fmt --check") -and ($prRaw -match "cargo clippy -- -D warnings")
}
Check "PR.md has Tests section + fmt/clippy lines" $prOk "follow the required verification plan format"
$parityOk = $prRaw -match "parity"
Check "PR.md notes parity (both paths)" $parityOk "mention legacy + state-machine check"
if ($parityOk) { Write-Host "PARITY-CHECK: OK" } else { Write-Host "PARITY-CHECK: FAILED" }
$smOk = $prRaw -match "GOOSE_STATE_MACHINE=1"
Check "PR.md mentions GOOSE_STATE_MACHINE=1 run" $smOk "line: state machine: GOOSE_STATE_MACHINE=1 run"
if ($smOk) { Write-Host "STATE-MACHINE-CHECK: OK" } else { Write-Host "STATE-MACHINE-CHECK: FAILED" }

# 5. Lightweight real checks on the tiny crate (fmt + clippy + tests)
if (Test-Path $crate) {
    Push-Location $crate
    try {
        $haveCargo = $null -ne (Get-Command cargo -ErrorAction SilentlyContinue)
        if ($haveCargo) {
            $ErrorActionPreference = "Continue"
            cargo fmt --check *> $null
            $fmtOk = ($LASTEXITCODE -eq 0)
            $ErrorActionPreference = "Stop"
            Check "cargo fmt --check passes" $fmtOk "run cargo fmt first"
            if ($fmtOk) { Write-Host "FMT-CONVENTION: OK" } else { Write-Host "FMT-CONVENTION: FAILED" }

            $ErrorActionPreference = "Continue"
            cargo clippy -- -D warnings *> $null
            $clipOk = ($LASTEXITCODE -eq 0)
            $ErrorActionPreference = "Stop"
            Check "cargo clippy -D warnings passes" $clipOk "fix remaining warnings"
            if ($clipOk) { Write-Host "CLIPPY-CONVENTION: OK" } else { Write-Host "CLIPPY-CONVENTION: FAILED" }

            $ErrorActionPreference = "Continue"
            cargo test --test truncate_label_regression *> $null
            $testOk = ($LASTEXITCODE -eq 0)
            $ErrorActionPreference = "Stop"
            Check "cargo test --test truncate_label_regression passes" $testOk "tests must pass both cases"
            if ($testOk) { Write-Host "TESTS: PASSED" } else { Write-Host "TESTS: FAILED" }
        } else {
            Check "cargo available for fmt/clippy/tests" $false "install Rust toolchain (Unit 0) and rerun"
        }
    } finally {
        Pop-Location
    }
} else {
    Check "fixer crate exists" $false "cargo new --lib u2-exam-fork/fixer"
}

Write-Host ""
if ($fails -eq 0) {
    Write-Host "VERIFY PASSED $passes/$($passes + $fails)"
    exit 0
} else {
    Write-Host "VERIFY FAILED - $fails of $($passes + $fails) checks failed"
    exit 1
}
